#include <stdio.h>
#include <stdlib.h>

#define MAX_N 100000
#define MAX_M 200000

typedef struct {
    int to;
    int next;
} Edge;

Edge edges[MAX_M * 2];
int head[MAX_N + 1];
int edge_cnt = 0;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int parent[MAX_N + 1];
int depth[MAX_N + 1];
int subtree_size[MAX_N + 1];
int heavy_child[MAX_N + 1];
int chain_top[MAX_N + 1];
int pos[MAX_N + 1];
int current_pos = 0;

void dfs1(int u, int p) {
    parent[u] = p;
    depth[u] = (p == -1) ? 0 : depth[p] + 1;
    subtree_size[u] = 1;
    heavy_child[u] = -1;
    int max_size = 0;
    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (v == p) continue;
        dfs1(v, u);
        subtree_size[u] += subtree_size[v];
        if (subtree_size[v] > max_size) {
            max_size = subtree_size[v];
            heavy_child[u] = v;
        }
    }
}

void dfs2(int u, int top) {
    chain_top[u] = top;
    pos[u] = current_pos++;
    if (heavy_child[u] != -1) {
        dfs2(heavy_child[u], top);
    }
    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (v != parent[u] && v != heavy_child[u]) {
            dfs2(v, v);
        }
    }
}

int bit[MAX_N + 2];
int n;

void bit_update(int idx, int delta) {
    while (idx <= n) {
        bit[idx] += delta;
        idx += idx & -idx;
    }
}

int bit_query(int idx) {
    int sum = 0;
    while (idx > 0) {
        sum += bit[idx];
        idx -= idx & -idx;
    }
    return sum;
}

void range_update(int l, int r, int delta) {
    if (l > r) return;
    bit_update(l, delta);
    bit_update(r + 1, -delta);
}

void path_update(int u, int v) {
    while (chain_top[u] != chain_top[v]) {
        if (depth[chain_top[u]] < depth[chain_top[v]]) {
            int temp = u; u = v; v = temp;
        }
        range_update(pos[chain_top[u]], pos[u], 1);
        u = parent[chain_top[u]];
    }
    if (u != v) {
        if (depth[u] < depth[v]) {
            int temp = u; u = v; v = temp;
        }
        range_update(pos[v] + 1, pos[u], 1);
    }
}

int main() {
