typedef long long ll;

typedef struct {
    int to, next;
    ll w;
} Edge;

typedef struct {
    ll d;
    int v;
} HeapNode;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static void heap_push(HeapNode *heap, int *sz, ll d, int v) {
    int i = ++(*sz);
    heap[i].d = d;
    heap[i].v = v;
    while (i > 1) {
        int p = i >> 1;
        if (heap[p].d <= heap[i].d) break;
        HeapNode tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
    }
}

static HeapNode heap_pop(HeapNode *heap, int *sz) {
    HeapNode ret = heap[1];
    heap[1] = heap[(*sz)--];
    int i = 1;
    while (1) {
        int l = i << 1, r = l + 1, s = i;
        if (l <= *sz && heap[l].d < heap[s].d) s = l;
        if (r <= *sz && heap[r].d < heap[s].d) s = r;
        if (s == i) break;
        HeapNode tmp = heap[i];
        heap[i] = heap[s];
        heap[s] = tmp;
        i = s;
    }
    return ret;
}

