    for (int i = 0; i < M; i++) {
        int a, b;
        ll d;
        scanf("%d %d %lld", &a, &b, &d);
        edges[ecnt].to = b; edges[ecnt].w = d; edges[ecnt].next = head[a]; head[a] = ecnt++;
        edges[ecnt].to = a; edges[ecnt].w = d; edges[ecnt].next = head[b]; head[b] = ecnt++;
    }

    ll *A = (ll *)malloc(C * sizeof(ll));
    for (int i = 0; i < C; i++) scanf("%lld", &A[i]);
    qsort(A, C, sizeof(ll), cmp_ll);

    const ll INF = (1LL << 62);
    ll *dist = (ll *)malloc((N + 1) * sizeof(ll));
    for (int i = 1; i <= N; i++) dist[i] = INF;
    dist[1] = 0;

    HeapNode *heap = (HeapNode *)malloc((2 * M + N + 5) * sizeof(HeapNode));
    int hsz = 0;
