        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[to]) {
                dist[to] = nd;
                heap_push(heap, &hsz, nd, to);
            }
        }
    }

    ll ans = 0;
    for (int i = 2; i <= N; i++) {
        if (dist[i] == INF) continue;
        ll x = dist[i];
        int l = 0, r = C;
        while (l < r) {
            int mid = (l + r) >> 1;
            if (A[mid] <= x) l = mid + 1;
            else r = mid;
        }
        ans += l;
    }

    printf("%lld\n", ans);

    free(head);
    free(edges);
    free(A);
    free(dist);
    free(heap);
    return 0;
}

