public class Main {
    static class Edge {
        int to, cost;
        Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        List<Edge>[] graph = new ArrayList[N];
        for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()) - 1;
            int b = Integer.parseInt(st.nextToken()) - 1;
            int c = Integer.parseInt(st.nextToken());
            graph[a].add(new Edge(b, c));
            graph[b].add(new Edge(a, c));
        }

        int[] baseFare = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            baseFare[i] = Integer.parseInt(st.nextToken());
        }

        int[] increase = new int[K];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < K; i++) {
            increase[i] = Integer.parseInt(st.nextToken());
        }

        // Compute shortest distances from capital (city 0)
        long[] dist = new long[N];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
        pq.offer(new long[]{0, 0});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[0];
            long d = cur[1];
            if (d != dist[u]) continue;
            for (Edge e : graph[u]) {
                if (dist[e.to] > d + e.cost) {
                    dist[e.to] = d + e.cost;
                    pq.offer(new long[]{e.to, dist[e.to]});
                }
            }
        }

        // For each city, determine the minimal fare they ever pay
        long[] minFare = new long[N];
        for (int i = 0; i < N; i++) {
            if (dist[i] == Long.MAX_VALUE) {
                minFare[i] = Long.MAX_VALUE;
            } else {
                minFare[i] = baseFare[i] + dist[i];
            }
        }

        // Simulate fare increases and count dissatisfied cities
        long currentIncrease = 0;
        int dissatisfied = 0;
        // Track which cities are already dissatisfied
        boolean[] isDissatisfied = new boolean[N];

        for (int i = 0; i < K; i++) {
            currentIncrease += increase[i];
            for (int city = 0; city < N; city++) {
                if (!isDissatisfied[city] && minFare[city] != Long.MAX_VALUE) {
                    // Compare current fare: original + currentIncrease
                    long currentFare = baseFare[city] + currentIncrease + dist[city];
                    if (currentFare > minFare[city]) {
                        isDissatisfied[city] = true;
                        dissatisfied++;
                    }
                }
            }
        }

        System.out.println(dissatisfied);
    }
}

