        u[i]--; v[i]--;
        g[u[i]].push_back({v[i], i});
        g[v[i]].push_back({u[i], i});
    }

    // Find bridges using Tarjan
    vector<int> tin(N, -1), low(N, -1);
    vector<bool> isBridge(M, false);
    int timer = 0;

    function<void(int, int)> dfs = [&](int v, int p_edge) {
        tin[v] = low[v] = timer++;
        for (auto &e : g[v]) {
            if (e.id == p_edge) continue;
            if (tin[e.to] != -1) {
                low[v] = min(low[v], tin[e.to]);
            } else {
                dfs(e.to, e.id);
                low[v] = min(low[v], low[e.to]);
                if (low[e.to] > tin[v]) {
                    isBridge[e.id] = true;
                }
            }
        }
    };

    for (int i = 0; i < N; i++) {
        if (tin[i] == -1) dfs(i, -1);
    }

    // Build bridge tree (component graph)
    vector<int> comp(N, -1);
    int comp_cnt = 0;

    function<void(int, int)> mark_comp = [&](int v, int c) {
        comp[v] = c;
        for (auto &e : g[v]) {
            if (comp[e.to] == -1 && !isBridge[e.id]) {
                mark_comp(e.to, c);
            }
        }
    };

    for (int i = 0; i < N; i++) {
        if (comp[i] == -1) {
            mark_comp(i, comp_cnt++);
        }
    }

    // Build tree of components
    vector<vector<pair<int,int>>> tree(comp_cnt); // (neighbor, edge_id)
    for (int i = 0; i < M; i++) {
        if (isBridge[i]) {
            int a = comp[u[i]], b = comp[v[i]];
            tree[a].push_back({b, i});
            tree[b].push_back({a, i});
        }
    }

    // Preprocess LCA and edge depths for binary lifting
    const int LOG = 20;
    vector<int> depth(comp_cnt, 0);
    vector<vector<int>> up(comp_cnt, vector<int>(LOG, -1));
    vector<int> edge_to_parent(comp_cnt, -1); // edge id to parent

    function<void(int, int)> dfs_tree = [&](int v, int p) {
        up[v][0] = p;
        for (int j = 1; j < LOG; j++) {
            if (up[v][j-1] != -1) up[v][j] = up[up[v][j-1]][j-1];
            else up[v][j] = -1;
        }
        for (auto &[to, eid] : tree[v]) {
            if (to == p) continue;
            depth[to] = depth[v] + 1;
            edge_to_parent[to] = eid;
            dfs_tree(to, v);
        }
    };

    // Find root for each tree (forest)
    vector<bool> visited_comp(comp_cnt, false);
    for (int i = 0; i < comp_cnt; i++) {
        if (!visited_comp[i]) {
            dfs_tree(i, -1);
            // mark all in this tree visited (since dfs_tree only goes down)
            // We need to actually mark visited properly
        }
    }
    // Better: just run dfs from all unvisited
    fill(visited_comp.begin(), visited_comp.end(), false);
    for (int i = 0; i < comp_cnt; i++) {
        if (!visited_comp[i]) {
            // BFS/DFS to mark
            stack<int> st;
            st.push(i);
            visited_comp[i] = true;
            depth[i] = 0;
            up[i][0] = -1;
            while (!st.empty()) {
                int v = st.top(); st.pop();
                for (int j = 1; j < LOG; j++) {
                    if (up[v][j-1] != -1) up[v][j] = up[up[v][j-1]][j-1];
                    else up[v][j] = -1;
                }
                for (auto &[to, eid] : tree[v]) {
                    if (!visited_comp[to]) {
                        visited_comp[to] = true;
                        depth[to] = depth[v] + 1;
                        up[to][0] = v;
                        edge_to_parent[to] = eid;
                        st.push(to);
                    }
                }
            }
        }
    }

    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) swap(a, b);
        int diff = depth[a] - depth[b];
        for (int j = 0; j < LOG; j++) {
            if (diff & (1 << j)) a = up[a][j];
        }
        if (a == b) return a;
        for (int j = LOG-1; j >= 0; j--) {
            if (up[a][j] != up[b][j]) {
                a = up[a][j];
                b = up[b][j];
            }
        }
        return up[a][0];
    };

    // Process fare increases
    vector<int> inc(M, 0); // number of times each edge fare increased
    for (int q = 0; q < Q; q++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        int ca = comp[a], cb = comp[b];
        if (ca == cb) {
            // within same component, no bridge affected
            continue;
        }
        int l = lca(ca, cb);
        // increase edges from ca to l
        int x = ca;
        while (x != l) {
            int eid = edge_to_parent[x];
            inc[eid]++;
            x = up[x][0];
        }
        // increase edges from cb to l
        x = cb;
