            int eid = edge_to_parent[x];
            inc[eid]++;
            x = up[x][0];
        }
    }

    // Count dissatisfied cities
    // A city is dissatisfied if all incident bridges have been increased at least once
    vector<int> bridge_deg(N, 0);
    vector<int> inc_bridge_cnt(N, 0);
    for (int i = 0; i < M; i++) {
        if (isBridge[i]) {
