    }

    int ans = 0;
    for (int i = 0; i < N; i++) {
        if (bridge_deg[i] > 0 && bridge_deg[i] == inc_bridge_cnt[i]) {
            ans++;
        }
    }

    cout << ans << "\n";

    return 0;
}

